tasks.setup:
// Old list: three rows, B is checked (uncontrolled state lives on its fiber)
var oldList = [
  { id: 'a', label: 'A' },
  { id: 'b', label: 'B' },
  { id: 'c', label: 'C' },
];
// New list after deleting the FIRST row (A). Data shifts up by one.
var newList = [
  { id: 'b', label: 'B' },
  { id: 'c', label: 'C' },
];

function diffByStableKey(oldArr, newArr) {
  var byKey = {};
  for (var i = 0; i < oldArr.length; i++) byKey[oldArr[i].id] = oldArr[i];
  var reused = 0, recreated = 0, mismatched = 0;
  for (var j = 0; j < newArr.length; j++) {
    var match = byKey[newArr[j].id]; // key = stable id
    if (match) {
      reused++;
      if (match.id !== newArr[j].id) mismatched++; // never happens: matched by id
    } else {
      recreated++;
    }
  }
  return { reused: reused, recreated: recreated, mismatched: mismatched };
}

function diffByIndexKey(oldArr, newArr) {
  var reused = 0, recreated = 0, mismatched = 0;
  for (var j = 0; j < newArr.length; j++) {
    var oldAtSameIndex = oldArr[j]; // key = position/index
    if (oldAtSameIndex) {
      reused++; // same index => React keeps this fiber
      if (oldAtSameIndex.id !== newArr[j].id) mismatched++; // fiber paired with wrong item
    } else {
      recreated++;
    }
  }
  return { reused: reused, recreated: recreated, mismatched: mismatched };
}

var stable = diffByStableKey(oldList, newList);
var index = diffByIndexKey(oldList, newList);
print('stable reused=' + stable.reused + ' recreated=' + stable.recreated + ' mismatched=' + stable.mismatched);
print('index reused=' + index.reused + ' recreated=' + index.recreated + ' mismatched=' + index.mismatched);

tasks.starter:
function TaskList({ tasks }) {
  // tasks can be re-sorted by the user; each <li> has an uncontrolled <input>
  return (
    <ul>
      {tasks.map((task, index) => (
        <li key={index}>
          <input defaultValue={task.title} />
        </li>
      ))}
    </ul>
  );
}
